    assert "+staged-only" in patch
    cloud = CLOUD_SCRIPT.read_text()
    fleet = fleet_source_text()
    assert 'cloudbench_worktree_has_changes "$ROOT_DIR"' in cloud
    assert fleet.count('cloudbench_worktree_has_changes "$ROOT_DIR"') >= 2


