@pytest.mark.parametrize("mode", ["hang", "cancel", "success", "missing", "malformed", "failure", "invalid-timeout", "zero-timeout", "double-zero-timeout"])
def test_verify_secrets_native_read_has_owned_deadline(tmp_path: Path, mode: str) -> None:
    """The actual early CLI entry must bound/reap native reads and fail closed."""
    import signal
    import time

    repo = tmp_path / "repo"
    lib = repo / "scripts/lib"
    lib.mkdir(parents=True)
    (repo / "agents").mkdir()
    (repo / "back-end").mkdir()
    for name in ("cloudbench-env.sh", "cloudbench-app-env-lock.sh"):
        (lib / name).write_text("# offline fixture: no provider operations\n")
    (lib / "cloudbench-github-token.sh").write_text("cloudbench_export_controller_github_token(){ return 0; }\n")
    bin_dir = tmp_path / "bin"
    bin_dir.mkdir()
    (bin_dir / "flyctl").write_text("""#!/usr/bin/env python3
import json, os, signal, sys, time
from pathlib import Path
assert sys.argv[1:] == ['secrets', 'list', '-a', 'navi-whisper-lux-bench', '--json']
mode = os.environ['READ_MODE']
if mode in ('hang', 'cancel'):
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    Path(os.environ['READ_PID']).write_text(str(os.getpid()))
    while True: time.sleep(1)
Path(os.environ['READ_PID']).write_text(str(os.getpid()))
if mode == 'failure': raise SystemExit(17)
if mode == 'malformed': print('not-json'); raise SystemExit(0)
names = 'AGENTS_ENV_B64 BACKEND_ENV_B64 AGENTS_ENV_SHA256 BACKEND_ENV_SHA256 CLOUDBENCH_BROWSER_PROVIDER GITHUB_TOKEN'.split()
print(json.dumps([{'Name': n} for n in (names if mode == 'success' else names[:-1])]))
""")
    (bin_dir / "flyctl").chmod(0o755)
    pid_file = tmp_path / "read.pid"
    env = {k: v for k, v in os.environ.items() if not k.startswith(("CLOUDBENCH_", "FLY_"))}
    env.update(CLOUDBENCH_FLEET_ROOT=str(repo), FLY_BENCH_API_TOKEN="offline-fixture-selected-token",
               PATH=str(bin_dir) + ":" + os.environ["PATH"], READ_PID=str(pid_file), READ_MODE=mode,
               CLOUDBENCH_APP_ENV_READ_TIMEOUT_SECONDS={"invalid-timeout": "invalid", "zero-timeout": "0", "double-zero-timeout": "00"}.get(mode, "1"))
    script = os.environ.get("CLOUDBENCH_CLOUD_SCRIPT_UNDER_TEST", str(CLOUD_SCRIPT))
    started = time.monotonic()
    proc = subprocess.Popen(["bash", script, "--verify-secrets"], env=env,
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, start_new_session=True)
    finished = False
    try:
        if mode == "cancel":
            deadline = time.monotonic() + 2
            while not pid_file.exists() and time.monotonic() < deadline:
                time.sleep(0.01)
            assert pid_file.exists(), "native read never started"
            os.killpg(proc.pid, signal.SIGTERM)
        try:
            stdout, stderr = proc.communicate(timeout=3.5)
            finished = True
        except subprocess.TimeoutExpired:
            pytest.fail("native secrets read outlived its configured deadline")
        elapsed = time.monotonic() - started
        if mode == "success":
            assert proc.returncode == 0 and "verified (read-only)" in stdout
        else:
            assert proc.returncode != 0 and "verified (read-only)" not in stdout
        if mode == "hang":
            assert "read exit=124" in stderr and elapsed < 3.5
        if mode == "missing":
            assert "missing secrets: GITHUB_TOKEN" in stderr
            assert "--refresh-secrets" in stderr
        else:
            assert "--setup" not in stderr and "--refresh-secrets" not in stderr, (
                "a failed read must not recommend mutating unverified app configuration"
            )
        if mode in {"invalid-timeout", "zero-timeout", "double-zero-timeout"}:
            assert not pid_file.exists(), "invalid deadline dispatched a native read"
        elif pid_file.exists():
            with pytest.raises(ProcessLookupError):
                os.kill(int(pid_file.read_text()), 0)
    finally:
        # This fixture created and still owns the isolated process session.
        if not finished:
            os.killpg(proc.pid, signal.SIGKILL)
            proc.communicate(timeout=2)


@pytest.mark.parametrize("kind", ["timeout", "malformed", "missing", "success"])
def test_fleet_environment_error_preserves_verifier_remediation(tmp_path: Path, kind: str) -> None:
    """Only a confirmed missing-name verdict authorizes the leaf's repair hint."""
    source = fleet_source_text()
    start = source.index("if ! verify_fleet_environment; then")
    end = source.index("\nfi", start) + len("\nfi")
    diagnostic = {
        "timeout": "Could not read app secrets (read exit=124).",
        "malformed": "Unreadable app secrets listing.",
        "missing": "Benchmark app environment is missing secrets: GITHUB_TOKEN\nRefresh explicitly: bash scripts/run-bench-cloud --refresh-secrets",
        "success": "Shared benchmark app environment verified (read-only).",
    }[kind]
    script = "verify_fleet_environment() { printf '%s\\n' \"$VERDICT\" >&2; return \"$VERDICT_CODE\"; };\n" + source[start:end]
    result = subprocess.run(["bash", "-c", script], capture_output=True, text=True,
                            env={**os.environ, "VERDICT": diagnostic, "VERDICT_CODE": "0" if kind == "success" else "1"}, timeout=3)
    assert result.returncode == (0 if kind == "success" else 1)
    assert diagnostic in result.stderr
    assert "--setup" not in result.stderr
    assert result.stderr.count("--refresh-secrets") == (1 if kind == "missing" else 0)
    if kind != "success":
        assert "no benchmark machine was started" in result.stderr


def test_environment_mutation_is_maintenance_only_and_run_path_read_only() -> None:
    cloud = CLOUD_SCRIPT.read_text()
    fleet = fleet_source_text()
    lock_lib = APP_ENV_LOCK_SCRIPT.read_text()

    # Maintenance ops (--setup / --refresh-wmh / --refresh-secrets) remain the
    # ONLY paths that mutate the shared app environment, and they still
    # serialize behind the cross-worktree app-environment lock.
    assert 'APP_ENV_LOCK_FILE="$GIT_COMMON_DIR/cloudbench-app-env.lock"' in cloud
    assert 'source "${CLOUDBENCH_SCRIPT_SNAPSHOT:-$ROOT_DIR/scripts/lib}/cloudbench-app-env-lock.sh"' in cloud
    assert 'shlock -p "$$" -f "$APP_ENV_LOCK_FILE"' in lock_lib
    wrapper_start = cloud.index("inject_secrets() {")
    wrapper_end = cloud.index("\n}\n", wrapper_start)
    wrapper = cloud[wrapper_start:wrapper_end]
    assert wrapper.index("acquire_app_environment_lock") < wrapper.index("( _inject_secrets_locked )")
    # The normal release follows injection; pre-injection failure branches also
    # release the lock, and the owning activation controls exercise those paths.
    assert wrapper.index("( _inject_secrets_locked )") < wrapper.rindex("release_app_environment_lock")
    locked_start = cloud.index("_inject_secrets_locked() {")
    locked_end = cloud.index("\n}\n", locked_start)
    assert 'FLY secrets set --stage -a "$APP"' in cloud[locked_start:locked_end]
    assert "CLOUDBENCH_HOLD_APP_ENV_LOCK=1" in cloud
    assert cloud.count("assert_app_environment_lock_ownership || exit 1") >= 2

    # The RUN path is concurrent-workstream safe: it reconciles its own pool,
    # then READ-ONLY verifies the shared environment. It never refreshes it,
    # never inherits another process's lock ownership, and never references
    # the app-environment lock at all.
    verify_call = 'bash "$RUN_BENCH_CLOUD_BIN" --verify-secrets'
    assert fleet.index("reconcile_pool || exit 1") < fleet.index(verify_call)
    assert fleet.index(verify_call) < fleet.index('        provision_primary_machine "$bench" "$out"')
    assert "run-bench-cloud --refresh-secrets;" not in fleet
    assert "APP_ENV_LOCK" not in fleet
    assert "acquire_app_environment_lock" not in fleet
    assert "CLOUDBENCH_APP_ENV_LOCK_OWNER_PID" not in cloud
    assert 'clone_machine_target "$out/worker-clones.ids" "$primary_id"' in fleet
    verify_start = cloud.index("verify_app_environment() {")
    verify_end = cloud.index("\n}\n", verify_start)
    verify = cloud[verify_start:verify_end]
    assert '_with_timeout "$read_timeout" flyctl secrets list -a "$APP" --json' in verify
    assert "secrets set" not in verify

    stop_cleanup_start = cloud.index("stop_on_exit() {")
    stop_cleanup_end = cloud.index("\n}", stop_cleanup_start)
    stop_cleanup = cloud[stop_cleanup_start:stop_cleanup_end]
    assert 'stop_machine "$mid"' in stop_cleanup
    assert "release_app_environment_lock" not in stop_cleanup

    cleanup_start = fleet.index("cleanup() {")
    cleanup_end = fleet.index("\n}", cleanup_start)
    cleanup = fleet[cleanup_start:cleanup_end]
    assert cleanup.index("trap - EXIT") < cleanup.index("cloudbench_terminate_tree_and_wait")
    assert cleanup.index("trap '' HUP INT TERM") < cleanup.index("cloudbench_terminate_tree_and_wait")
    assert (
        'if ! cloudbench_terminate_tree_and_wait "${CLOUDBENCH_CHILD_TERM_SECONDS:-30}" \\\n'
        '        "${AUTOSCALER_PIDS[@]:-}"; then'
    ) in cleanup
    assert (
        'if ! cloudbench_terminate_tree_and_wait "${CLOUDBENCH_CHILD_TERM_SECONDS:-30}" \\\n'
        '        "${PROVISION_PIDS[@]:-}"; then'
    ) in cleanup
    assert (
        'if ! cloudbench_terminate_tree_and_wait "${CLOUDBENCH_CHILD_TERM_SECONDS:-30}" \\\n'
        '        "${CHILD_PIDS[@]:-}"; then'
    ) in cleanup
    assert "CLOUDBENCH_CHILD_TERM_SECONDS:-30" in fleet
    helper = ENV_HELPER_SCRIPT.read_text()
    assert "cloudbench_terminate_and_wait() {" in helper
    assert "cloudbench_terminate_tree_and_wait() {" in helper
    assert "cloudbench_detach_reexec_tracked() {" in helper
    assert "cloudbench_wait_tracked_detached() {" in helper
    assert "ps -axo pid=,ppid=,lstart=" in helper
    assert "cloudbench_pid_matches_start" in helper
    assert 'kill -KILL "$pid"' in helper
    # fleet traps name the signal before exiting (still exit 129/130/143)
    assert "controller received HUP" in fleet and "exit 129' HUP" in fleet
    assert "trap 'exit 129' HUP" in cloud


def test_pool_reconcile_leaves_concurrent_owner_untouched(tmp_path: Path) -> None:
    fleet = fleet_source_text()
    function_start = fleet.index("pool_machine_state_from_json() {")
    reconcile_start = fleet.index("reconcile_pool() {", function_start)
    function_end = fleet.index("\n}\n", reconcile_start) + 3
