def test_startup_capacity_release_streams_full_provider_inventory_without_exec_size_limit(
    tmp_path: Path,
) -> None:
    """RCA (2026-07-21): epoch 15 reached 42/42 boot configs and starts,
    but the release check exported Fly's full 45-Machine JSON as ``INVENTORY``
    when launching Python. The provider event history made that environment
    exceed macOS ARG_MAX, so Python never ran, the 46-slot startup reservation
    stayed live, and six mandatory dynamic workers were denied.

    Provider inventory is unbounded process data. The release boundary now reads
    each exact primary through the bounded Machines API helper; exercise it
    against a loopback Machines API whose response is larger than this host's
    exec limit. It must still prove all exact primaries started and release the
    reservation.
    """
    fleet = fleet_source_text()
    release = _extract_fleet_function(fleet, "release_capacity_reservation_after_primary_start_accounted() {")
    machine_ids = [f"{index:014x}" for index in range(42)]
    outputs = []
    for index, machine_id in enumerate(machine_ids):
        output = tmp_path / f"bench-{index}"
        output.mkdir()
        (output / "post-config-start.accepted").write_text(f"{machine_id}\n")
        outputs.append(output)
    oversized = int(subprocess.run(["getconf", "ARG_MAX"], text=True, capture_output=True, check=True).stdout) + 65536
    seen: list[str] = []

    class MachinesApi(BaseHTTPRequestHandler):
        def do_GET(self) -> None:
            seen.append(self.path)
            machine_id = self.path.rsplit("/", 1)[-1]
            machine: dict[str, object] = {"id": machine_id, "state": "started"}
            if machine_id == machine_ids[0]:
                machine["events"] = ["x" * oversized]
            body = json.dumps(machine).encode()
            self.send_response(200)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, _format: str, *args: object) -> None:
            return

    server = ThreadingHTTPServer(("127.0.0.1", 0), MachinesApi)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    released = tmp_path / "released"
    benches = " ".join(f"bench-{index}" for index in range(42))
    child_outputs = " ".join(shlex.quote(str(output)) for output in outputs)
    script = f"""set -u
CAPACITY_RESERVATION_PUBLISHED=1
CAPACITY_RESERVATION_TOKEN=test-full-inventory
CLOUDBENCH_CAPACITY_START_ACCOUNTING_SECONDS=30
CLOUDBENCH_SCRIPT_SNAPSHOT={shlex.quote(str(ROOT / "scripts"))}
BENCHES=({benches})
CHILD_MACHINE=({" ".join(machine_ids)})
CHILD_OUT=({child_outputs})
APP=fixture-bench-app
FLY() {{ echo "unexpected full inventory list: $*" >&2; return 1; }}
capacity_release_reservation() {{ touch {shlex.quote(str(released))}; }}
{release}
release_capacity_reservation_after_primary_start_accounted
"""
    try:
        result = subprocess.run(
            ["bash", "-c", script],
            env={
                **os.environ,
                "inventory": "sentinel",
                "machines_json": "sentinel",
                "FLY_API_TOKEN": "Bearer synthetic-only-token",
                "FLY_FLAPS_BASE_URL": f"http://127.0.0.1:{server.server_port}",
            },
            text=True,
            capture_output=True,
            check=False,
            timeout=60,
        )
    finally:
        server.shutdown()
        server.server_close()

    assert result.returncode == 0, result.stderr
    assert released.exists()
    assert sorted(seen) == sorted(f"/v1/apps/fixture-bench-app/machines/{machine_id}" for machine_id in machine_ids)


def test_capacity_reservation_recovers_a_proven_dead_owner(tmp_path: Path) -> None:
    """SIGKILL must not wedge host-wide admission forever.

    A reservation is recoverable only when its same-host PID and exact process
    birth identity are no longer live.  The successor must prune that record
    while holding the admission lock, then publish its own reservation.
    """
    fleet = fleet_source_text()
    reserve = _extract_fleet_function(fleet, "capacity_reserve_slots() {")
    root = tmp_path / "reservations-root"
    records = root / "reservations"
    records.mkdir(parents=True)
    dead_token = "e" * 32 + "-primary"
    live_token = "f" * 32 + "-primary"
    (records / dead_token).write_text(
        "version=1\n"
        "app=fixture-bench-app\n"
        f"host={socket.gethostname()}\n"
        "pid=999999\n"
        "pid_start=Mon Jan  1 00:00:00 2001\n"
        "run_id=dead-owner\n"
        f"token={dead_token}\n"
        "machine_slots=50\n"
        "shared_units=100\n"
        "kind=primary\n"
    )
    script = f"""set -eu
CAPACITY_RESERVATION_ROOT={shlex.quote(str(root))}
APP=fixture-bench-app
FLEET_OWNER_HOST="$(hostname)"
FLEET_OWNER_PID_START="$(ps -p $$ -o lstart= | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')"
RUN_ID=successor
{reserve}
capacity_reserve_slots {live_token} 1 2 56 140 10 20 primary
test ! -e {shlex.quote(str(records / dead_token))}
test -f {shlex.quote(str(records / live_token))}
"""
    result = subprocess.run(["bash", "-c", script], text=True, capture_output=True, check=False)

    assert result.returncode == 0, result.stderr
    assert result.stdout.startswith("OK ")


def test_capacity_reservation_retains_cleanup_unconfirmed_dead_owner(
    tmp_path: Path,
) -> None:
    """Admission must not prune ownership while its guest cleanup is unresolved."""
    fleet = fleet_source_text()
    reserve = _extract_fleet_function(fleet, "capacity_reserve_slots() {")
    root = tmp_path / "reservations-root"
    records = root / "reservations"
    ownership_root = tmp_path / "fleet-ownership"
    records.mkdir(parents=True)
    owner_token = "d" * 32
    dead_token = owner_token + "-primary"
    live_owner_token = "e" * 32
    live_token = live_owner_token + "-primary"
    registry = ownership_root / owner_token
    registry.mkdir(parents=True)
    (registry / "guest-cleanup-unconfirmed").touch()
    (records / dead_token).write_text(
        "version=1\n"
        "app=fixture-bench-app\n"
        f"host={socket.gethostname()}\n"
        "pid=999999\n"
        "pid_start=Mon Jan  1 00:00:00 2001\n"
        "run_id=dead-owner\n"
        f"token={dead_token}\n"
        f"fleet_owner_token={owner_token}\n"
        "machine_slots=50\n"
        "shared_units=100\n"
        "kind=primary\n"
    )
    script = f"""set -u
CAPACITY_RESERVATION_ROOT={shlex.quote(str(root))}
FLEET_OWNERSHIP_ROOT={shlex.quote(str(ownership_root))}
APP=fixture-bench-app
FLEET_OWNER_HOST="$(hostname)"
FLEET_OWNER_PID_START="$(ps -p $$ -o lstart= | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')"
FLEET_OWNER_TOKEN={live_owner_token}
RUN_ID=successor
{reserve}
capacity_reserve_slots {live_token} 1 2 56 140 10 20 primary
"""
    result = subprocess.run(["bash", "-c", script], text=True, capture_output=True, check=False)

    assert result.returncode == 1, result.stderr
    assert result.stdout.startswith("DENY_MACHINE ")
    assert (records / dead_token).exists()
    assert not (records / live_token).exists()


def test_autoscaler_worker_clones_take_a_serialized_machine_slot() -> None:
    """Post-start autoscaling must not bypass Machine-count admission."""
    fleet = fleet_source_text()
    worker = _extract_fleet_function(fleet, "provision_worker() {")

    assert 'reserve_worker_machine_slot "$worker_capacity_token"' in worker
    assert worker.index("reserve_worker_machine_slot") < worker.index("clone_machine_target")
    assert 'capacity_release_reservation "$worker_capacity_token"' in worker
    clone = worker.index('wid="$(clone_machine_target')
    assert worker.index('reserve_worker_machine_slot "$worker_capacity_token"') < clone
    assert clone < worker.index('if ! capacity_release_reservation "$worker_capacity_token";')


def test_watchdog_collects_cancelled_artifact_after_bounded_shutdown(tmp_path: Path) -> None:
    """Shutdown writes the terminal artifact after the last watchdog poll."""
    cloud = CLOUD_SCRIPT.read_text()
    collection = cloud[
        cloud.index("# Preserve the complete remote driver") : cloud.index(
            "RUN_IDENTITY_OK=", cloud.index("# Preserve the complete remote driver")
        )
    ]
    collect = _extract_fleet_function(cloud, "cloudbench_collect_terminal_log() {")
    script = f"""set -eu
{collect}
ROOT_DIR="$1"
OUT_DIR="$1/out"
mkdir -p "$OUT_DIR"
SSH_LOG="$1/driver.log"
printf '%s\\n' 'RUNSTAMP-run-token' > "$SSH_LOG"
CLOUDBENCH_BOOT_LAUNCH=1
NEEDS_IMESSAGE_RELAY=0
RUN_WORKSPACE_NAME=fixture
REPORT_BEGIN=REPORT-BEGIN
REPORT_END=REPORT-END
RESULT_BEGIN=RESULT-BEGIN
RESULT_END=RESULT-END
DONE_MARKER='::CLOUDBENCH-DONE:: token=run-token'
TIMED_OUT=1
FINISHED=0
BENCH_EXIT=''
FLEET_MACHINE_ID=fixture-machine
LOCAL_STATUS_PORT=1
RUN_LOG_TOKEN=run-token
cloudbench_skip_held_driver_teardown_race() {{ return 1; }}
# This fixture owns shutdown/run extraction. The adjacent real HTTP fixture
# exercises the complete raw-log transport.
cloudbench_collect_runtime_evidence() {{
  [ -f "$ROOT_DIR/sealed-run.json" ]
  mkdir -p "$1/runtime-evidence"
  cp "$ROOT_DIR/sealed-run.json" "$1/runtime-evidence/run.json"
}}
confirm_guest_shutdown() {{
  printf '%s\\n' shutdown > "$ROOT_DIR/order"
  printf '%s\\n' \\
    '{{"tasks":[{{"name":"fixture","passed":false,"status":"ACTIVE","benchmark_status":"CANCELLED"}}]}}' \\
    > "$ROOT_DIR/sealed-run.json"
  printf '%s\\n' 'RUNSTAMP-run-token' 'RESULT-BEGIN' \\
    '{{"tasks":[{{"name":"fixture","passed":true,"status":"ACTIVE","benchmark_status":"PASSED"}}]}}' \\
    'RESULT-END' '::CLOUDBENCH-DONE:: token=run-token exit=1' > "$ROOT_DIR/remote.log"
}}
refresh_bench_log_to_eof() {{
  printf '%s\\n' collect >> "$ROOT_DIR/order"
  cp "$ROOT_DIR/remote.log" "$SSH_LOG"
}}
{collection}
[ "$TIMED_OUT" = 1 ]
[ "$FINISHED" = 1 ]
[ "$BENCH_EXIT" = 1 ]
[ "$GUEST_SHUTDOWN_RESULT" = 0 ]
printf '%s\\n' "$RUN_JSON" > "$ROOT_DIR/result.json"
"""
    # No process, provider, or network is involved: only the real controller's
    # post-poll collection block and its token-bound artifact parser execute.
    result = subprocess.run(
        ["bash", "-c", script, "watchdog-collection", str(tmp_path)],
        text=True,
        capture_output=True,
        check=False,
        timeout=5,
    )
    assert result.returncode == 0, result.stderr
    assert (tmp_path / "order").read_text().splitlines() == ["shutdown", "collect"]
    task = json.loads((tmp_path / "result.json").read_text())["tasks"][0]
    assert task["benchmark_status"] == "CANCELLED"
    assert task["passed"] is False


